function maxEqualFreq(nums) {
  const count = new Map();
  const freqOf = new Map();
  let maxFreq = 0;
  let best = 0;

  for (let i = 0; i < nums.length; i++) {
    const old = count.get(nums[i]) ?? 0;
    const now = old + 1;
    count.set(nums[i], now);
    if (old > 0) {
      freqOf.set(old, freqOf.get(old) - 1);
    }
    freqOf.set(now, (freqOf.get(now) ?? 0) + 1);
    maxFreq = Math.max(maxFreq, now);

    const length = i + 1;
    const atMax = freqOf.get(maxFreq);
    const belowMax = freqOf.get(maxFreq - 1) ?? 0;
    if (maxFreq === 1) {
      best = length;
    } else if (atMax * maxFreq + 1 === length) {
      best = length;
    } else if (belowMax * (maxFreq - 1) + maxFreq === length) {
      best = length;
    }
  }
  return best;
}

