function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const limit = size === 'large' ? 2000 : int(2, 10);
  const top = size === 'large' ? 100000 : 6;
  const distinct = size === 'large' ? int(1, 60) : int(1, 4);
  const pool = Array.from({ length: distinct }, () => int(1, top));
  const nums = [];
  if (rand() < 0.5) {
    // Rounds of shuffled values make many prefixes balanced or nearly so.
    while (nums.length < limit) {
      const round = pool.slice();
      for (let i = round.length - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        [round[i], round[j]] = [round[j], round[i]];
      }
      for (const v of round) if (nums.length < limit && rand() < 0.9) nums.push(v);
    }
  } else {
    while (nums.length < limit) nums.push(pool[Math.floor(rand() * pool.length)]);
  }
  const noise = size === 'large' ? int(0, 5) : int(0, 1);
  for (let i = 0; i < noise; i++) nums[int(0, nums.length - 1)] = int(1, top);
  while (nums.length < 2) nums.push(int(1, top));
  return [nums];
}
